@Test
public void testClone() {
    BaseFileInputFiles orig = new BaseFileInputFiles();
    orig.fileName = new String[] { "1", "2" };
    orig.fileMask = new String[] { "3", "4" };
    orig.excludeFileMask = new String[] { "5", "6" };
