@Test
public void runMapTests() throws IOException {
    Properties p = new Properties();
    ConcurrentMapProperties c = new ConcurrentMapProperties();
    for (int i = 0; i < 10000; i++) {
        String unique = UUID.randomUUID().toString();
        p.put(unique, unique);
        c.put(unique, unique);
    }
    Assert.assertTrue(p.equals(c));
    Assert.assertEquals(p.size(), c.size());
    List<String> removeKeys = new ArrayList<>(c.size());
    for (Object key : c.keySet()) {
        if (Math.random() > 0.2) {
            removeKeys.add((String) key);
        }
    }
    for (String rmKey : removeKeys) {
        c.remove(rmKey);
        p.remove(rmKey);
    }
    Assert.assertEquals(p.size(), c.size());
    Assert.assertTrue(p.equals(c));
    p.clear();
    c.clear();
    Assert.assertTrue(p.equals(c));
    Assert.assertEquals(0, p.size());
    Assert.assertEquals(0, c.size());
    Map<String, String> addKeys = removeKeys.stream().collect(Collectors.toMap(x -> x, x -> x));
    p.putAll(addKeys);
    c.putAll(addKeys);
    Assert.assertTrue(p.equals(c));
    for (String property : removeKeys) {
        Assert.assertEquals(p.getProperty(property), c.getProperty(property));
    }
    Path tempFile = Files.createTempFile("propstest", "props");
    c.store(new FileOutputStream(tempFile.toFile()), "No Comments");
    c.clear();
    Assert.assertEquals(0, c.size());
    c.load(new FileInputStream(tempFile.toFile()));
    Assert.assertEquals(c, p);
}

@Test
public // PDI-11389 Number of job trackers should be limited by HOP_MAX_JOB_TRACKER_SIZE
void testAddJobTracker() throws Exception {
    final String old = System.getProperty(Const.HOP_MAX_JOB_TRACKER_SIZE);
    final Integer maxTestSize = 30;
    try {
        System.setProperty(Const.HOP_MAX_JOB_TRACKER_SIZE, maxTestSize.toString());
        JobMeta jobMeta = mock(JobMeta.class);
        JobTracker jobTracker = new JobTracker(jobMeta);
        for (int n = 0; n < maxTestSize * 2; n++) {
            jobTracker.addJobTracker(mock(JobTracker.class));
        }
        assertTrue("More JobTrackers than allowed were added", jobTracker.getTotalNumberOfItems() <= maxTestSize);
    } finally {
        if (old == null) {
            System.clearProperty(Const.HOP_MAX_JOB_TRACKER_SIZE);
        } else {
            System.setProperty(Const.HOP_MAX_JOB_TRACKER_SIZE, old);
        }
    }
}

