    assertNull(ValueMetaBase.convertStringToBoolean(""));
    assertTrue(ValueMetaBase.convertStringToBoolean("Y"));
    assertTrue(ValueMetaBase.convertStringToBoolean("y"));
    assertTrue(ValueMetaBase.convertStringToBoolean("Yes"));
    assertTrue(ValueMetaBase.convertStringToBoolean("YES"));
    assertTrue(ValueMetaBase.convertStringToBoolean("yES"));
    assertTrue(ValueMetaBase.convertStringToBoolean("TRUE"));
    assertTrue(ValueMetaBase.convertStringToBoolean("True"));
    assertTrue(ValueMetaBase.convertStringToBoolean("true"));
    assertTrue(ValueMetaBase.convertStringToBoolean("tRuE"));
    assertTrue(ValueMetaBase.convertStringToBoolean("Y"));
    assertFalse(ValueMetaBase.convertStringToBoolean("N"));
    assertFalse(ValueMetaBase.convertStringToBoolean("No"));
    assertFalse(ValueMetaBase.convertStringToBoolean("no"));
    assertFalse(ValueMetaBase.convertStringToBoolean("Yeah"));
    assertFalse(ValueMetaBase.convertStringToBoolean("False"));
    assertFalse(ValueMetaBase.convertStringToBoolean("NOT false"));
}

@Test
public void testConvertDataFromStringToString() throws HopValueException {
    ValueMetaBase inValueMetaString = new ValueMetaString();
    ValueMetaBase outValueMetaString = new ValueMetaString();
    String inputValueEmptyString = StringUtils.EMPTY;
    String inputValueNullString = null;
    String nullIf = null;
    String ifNull = null;
    int trim_type = 0;
    Object result;
    System.setProperty(Const.HOP_EMPTY_STRING_DIFFERS_FROM_NULL, "N");
    result = outValueMetaString.convertDataFromString(inputValueEmptyString, inValueMetaString, nullIf, ifNull, trim_type);
    assertEquals("HOP_EMPTY_STRING_DIFFERS_FROM_NULL = N: " + "Conversion from empty string to string must return empty string", StringUtils.EMPTY, result);
    result = outValueMetaString.convertDataFromString(inputValueNullString, inValueMetaString, nullIf, ifNull, trim_type);
    assertEquals("HOP_EMPTY_STRING_DIFFERS_FROM_NULL = N: " + "Conversion from null string must return null", null, result);
    System.setProperty(Const.HOP_EMPTY_STRING_DIFFERS_FROM_NULL, "Y");
    result = outValueMetaString.convertDataFromString(inputValueEmptyString, inValueMetaString, nullIf, ifNull, trim_type);
    assertEquals("HOP_EMPTY_STRING_DIFFERS_FROM_NULL = Y: " + "Conversion from empty string to string must return empty string", StringUtils.EMPTY, result);
    result = outValueMetaString.convertDataFromString(inputValueNullString, inValueMetaString, nullIf, ifNull, trim_type);
    assertEquals("HOP_EMPTY_STRING_DIFFERS_FROM_NULL = Y: " + "Conversion from null string must return empty string", StringUtils.EMPTY, result);
}

